"""Code parser: extract SCPI commands from C, C++, and Python source code."""

from __future__ import annotations
import re
from dataclasses import dataclass, field
from typing import List, Optional
import ast


@dataclass
class ParsedCommand:
    scpi_command: str
    line_number: int
    source_language: str
    context: str = ""       # surrounding code snippet
    is_query: bool = False
    variable_name: Optional[str] = None  # for query assignments


class CodeParser:
    """Extracts SCPI command strings from C, C++, or Python source code.

    Heuristic approach: looks for common VISA/SCPI library call patterns:
    - C/C++: viPrintf, viWrite, visa_write, scpi_send, send_command,
             viQueryf, viRead, ibwrt, ibrd, GPIB_write, etc.
    - Python: inst.write(), inst.query(), pyvisa write/query,
              visa.write(), rm.open_resource().write(), etc.
    """

    # Patterns for C/C++ SCPI writes
    C_WRITE_PATTERNS = [
        r'vi(?:Write|Printf)\s*\([^,]+,\s*"([^"]+)"',
        r'visa_write\s*\([^,]+,\s*"([^"]+)"',
        r'scpi_send\s*\([^,]+,\s*"([^"]+)"',
        r'send_command\s*\([^,)]*"([^"]+)"',
        r'ibwrt\s*\([^,]+,\s*"([^"]+)"',
        r'GPIB_write\s*\([^,]+,\s*"([^"]+)"',
        r'instrument_write\s*\([^,)]*"([^"]+)"',
        r'scpi_write\s*\([^,)]*"([^"]+)"',
        r'cmd_write\s*\([^,)]*"([^"]+)"',
        r'fprintf\s*\([^,]+,\s*"([^"]+)"',
        r'sprintf\s*\([^,]+,\s*"([^"]+)"',
        r'printf\s*\(\s*"([A-Z][A-Z0-9:*?][^"]*)"',  # Bare printf with SCPI-like string
    ]

    # Patterns for C/C++ SCPI queries
    C_QUERY_PATTERNS = [
        r'(?:(\w+)\s*=\s*)?vi(?:QueryF|Query)\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?visa_query\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?scpi_query\s*\([^,]+,\s*"([^"]+)"',
        r'(?:(\w+)\s*=\s*)?query_command\s*\([^,)]*"([^"]+)"',
    ]

    # Python write patterns
    PY_WRITE_PATTERNS = [
        r'(?:\w+)\.write\s*\(\s*[f\'"]([^\'"]+)[\'"]',
        r'(?:\w+)\.write\s*\(\s*f"([^"]+)"',
        r'send_scpi\s*\(\s*[\'"]([^\'"]+)[\'"]',
        r'scpi\s*\(\s*[\'"]([^\'"]+)[\'"]',
        r'instrument\.write\s*\(\s*[\'"]([^\'"]+)[\'"]',
    ]

    # Python query patterns
    PY_QUERY_PATTERNS = [
        r'(?:(\w+)\s*=\s*)?(?:\w+)\.query\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
        r'(?:(\w+)\s*=\s*)?(?:\w+)\.ask\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
        r'(?:(\w+)\s*=\s*)?query_scpi\s*\(\s*[\'"]([^\'"?]+\??)[\'"]',
    ]

    # SCPI-like string heuristic: starts with *IDN, *RST or WORD[:] pattern
    SCPI_HEURISTIC = re.compile(
        r'^(\*[A-Z]+|[A-Z][A-Z0-9_]+(?::[A-Z0-9_]+)*)[\s?]',
        re.IGNORECASE
    )

    def parse(self, code: str, language: str = "auto") -> List[ParsedCommand]:
        """Parse source code and return list of extracted SCPI commands."""
        if not code.strip():
            return []

        if language == "auto":
            language = self._detect_language(code)

        if language in ("c", "cpp", "c++"):
            return self._parse_c(code)
        elif language == "python":
            return self._parse_python(code)
        else:
            # Try both
            c_cmds = self._parse_c(code)
            py_cmds = self._parse_python(code)
            return c_cmds + py_cmds

    def _detect_language(self, code: str) -> str:
        if "#include" in code or "viWrite" in code or "ibwrt" in code:
            return "cpp"
        if "def " in code or "import " in code or ".write(" in code:
            return "python"
        if "::" in code or "std::" in code:
            return "cpp"
        return "auto"

    def _parse_c(self, code: str) -> List[ParsedCommand]:
        cmds: List[ParsedCommand] = []
        lines = code.split("\n")

        for lineno, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped.startswith("//") or stripped.startswith("/*"):
                continue

            # Queries first (order matters — queries have more groups)
            for pattern in self.C_QUERY_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    var = m.group(1) if m.lastindex and m.lastindex >= 2 and m.group(1) else None
                    scpi = m.group(2) if m.lastindex and m.lastindex >= 2 else m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        cmd_str = scpi.rstrip() + ("?" if not scpi.strip().endswith("?") else "")
                        cmds.append(ParsedCommand(
                            scpi_command=cmd_str,
                            line_number=lineno,
                            source_language="c",
                            context=stripped[:80],
                            is_query=True,
                            variable_name=var,
                        ))

            # Writes
            for pattern in self.C_WRITE_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        is_q = scpi.strip().endswith("?")
                        cmds.append(ParsedCommand(
                            scpi_command=scpi.strip(),
                            line_number=lineno,
                            source_language="c",
                            context=stripped[:80],
                            is_query=is_q,
                        ))

        return self._deduplicate(cmds)

    def _parse_python(self, code: str) -> List[ParsedCommand]:
        cmds: List[ParsedCommand] = []
        lines = code.split("\n")

        for lineno, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped.startswith("#"):
                continue

            # Python queries
            for pattern in self.PY_QUERY_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    if m.lastindex and m.lastindex >= 2:
                        var = m.group(1)
                        scpi = m.group(2)
                    else:
                        var = None
                        scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        cmd_str = scpi.rstrip()
                        if not cmd_str.endswith("?"):
                            cmd_str += "?"
                        cmds.append(ParsedCommand(
                            scpi_command=cmd_str,
                            line_number=lineno,
                            source_language="python",
                            context=stripped[:80],
                            is_query=True,
                            variable_name=var,
                        ))

            # Python writes
            for pattern in self.PY_WRITE_PATTERNS:
                for m in re.finditer(pattern, line, re.IGNORECASE):
                    scpi = m.group(1)
                    if scpi and self._looks_like_scpi(scpi):
                        # Strip f-string format specifiers ({...})
                        scpi_clean = re.sub(r'\{[^}]*\}', '<VAR>', scpi).strip()
                        is_q = scpi_clean.endswith("?")
                        cmds.append(ParsedCommand(
                            scpi_command=scpi_clean,
                            line_number=lineno,
                            source_language="python",
                            context=stripped[:80],
                            is_query=is_q,
                        ))

        # Also try AST-based extraction for Python
        try:
            ast_cmds = self._parse_python_ast(code)
            cmds.extend(ast_cmds)
        except SyntaxError:
            pass

        return self._deduplicate(cmds)

    def _parse_python_ast(self, code: str) -> List[ParsedCommand]:
        """Use Python AST to find string literals that look like SCPI commands."""
        cmds: List[ParsedCommand] = []
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return cmds

        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                s = node.value.strip()
                if self._looks_like_scpi(s) and len(s) > 2:
                    lineno = getattr(node, 'lineno', 0)
                    is_q = s.endswith("?")
                    cmds.append(ParsedCommand(
                        scpi_command=s,
                        line_number=lineno,
                        source_language="python",
                        context="(AST string literal)",
                        is_query=is_q,
                    ))

        return cmds

    def _looks_like_scpi(self, s: str) -> bool:
        """Heuristic: does this string look like a SCPI command?"""
        s = s.strip()
        if not s or len(s) < 2:
            return False
        # Must start with * or uppercase word followed by : or space or ?
        return bool(self.SCPI_HEURISTIC.match(s + " "))

    @staticmethod
    def _deduplicate(cmds: List[ParsedCommand]) -> List[ParsedCommand]:
        seen = set()
        result = []
        for cmd in cmds:
            key = (cmd.scpi_command, cmd.line_number)
            if key not in seen:
                seen.add(key)
                result.append(cmd)
        return sorted(result, key=lambda c: c.line_number)

"""Multi-file SCPI extraction for whole projects (e.g. flight OS, RTOS).

The single-buffer ``CodeParser`` works for one pasted snippet. Real
HIL/SIL/CIL test inputs are usually a tree: a flight OS, a driver layer,
unit-test harnesses, third-party libs. ``CodeProject`` walks that tree,
parses every recognized source file, and returns the extracted commands
keyed by the file they came from so the GUI can display and route them
in original execution order.
"""
from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence

from silmulator.code_parser.base_parser import CodeParser, ParsedCommand


SOURCE_EXTENSIONS: Dict[str, str] = {
    ".c": "c",
    ".h": "c",
    ".cc": "cpp",
    ".cpp": "cpp",
    ".cxx": "cpp",
    ".hpp": "cpp",
    ".hh": "cpp",
    ".py": "python",
}

DEFAULT_IGNORES: Sequence[str] = (
    ".git", ".svn", ".hg",
    "__pycache__", ".venv", "venv", "env", ".env",
    "build", "dist", "node_modules", ".tox", ".mypy_cache",
    ".pytest_cache", "cmake-build-debug", "cmake-build-release",
    "target", "out",
)


@dataclass
class ParsedFile:
    path: Path
    language: str
    commands: List[ParsedCommand] = field(default_factory=list)
    error: Optional[str] = None

    @property
    def relative(self) -> str:
        return str(self.path)


@dataclass
class CodeProject:
    """A parsed view of a directory of source files."""

    root: Path
    files: List[ParsedFile] = field(default_factory=list)
    ignored_dirs: Sequence[str] = field(default_factory=lambda: tuple(DEFAULT_IGNORES))
    max_file_bytes: int = 2_000_000  # 2 MB per file is plenty for source

    @classmethod
    def from_path(
        cls,
        root: os.PathLike,
        ignored_dirs: Optional[Sequence[str]] = None,
        max_file_bytes: int = 2_000_000,
    ) -> "CodeProject":
        root_path = Path(root).expanduser().resolve()
        if not root_path.exists():
            raise FileNotFoundError(root_path)
        proj = cls(
            root=root_path,
            ignored_dirs=tuple(ignored_dirs) if ignored_dirs is not None else tuple(DEFAULT_IGNORES),
            max_file_bytes=max_file_bytes,
        )
        proj.refresh()
        return proj

    def refresh(self) -> None:
        parser = CodeParser()
        self.files = []
        for src_path, language in self._walk():
            try:
                size = src_path.stat().st_size
            except OSError as e:
                self.files.append(ParsedFile(src_path, language, error=str(e)))
                continue
            if size > self.max_file_bytes:
                self.files.append(ParsedFile(
                    src_path, language,
                    error=f"skipped: file too large ({size} bytes)"
                ))
                continue
            try:
                code = src_path.read_text(encoding="utf-8", errors="replace")
            except OSError as e:
                self.files.append(ParsedFile(src_path, language, error=str(e)))
                continue
            cmds = parser.parse(code, language)
            self.files.append(ParsedFile(src_path, language, commands=cmds))

    def _walk(self) -> Iterable[tuple[Path, str]]:
        if self.root.is_file():
            lang = SOURCE_EXTENSIONS.get(self.root.suffix.lower())
            if lang:
                yield self.root, lang
            return
        ignored = set(self.ignored_dirs)
        for dirpath, dirnames, filenames in os.walk(self.root):
            dirnames[:] = [d for d in dirnames if d not in ignored and not d.startswith(".")]
            for name in filenames:
                ext = Path(name).suffix.lower()
                lang = SOURCE_EXTENSIONS.get(ext)
                if lang is None:
                    continue
                yield Path(dirpath) / name, lang

    # ------------------------------------------------------------------
    # Convenience accessors used by the GUI / runner
    # ------------------------------------------------------------------

    def all_commands(self) -> List[ParsedCommand]:
        out: List[ParsedCommand] = []
        for f in self.files:
            out.extend(f.commands)
        return out

    def total_commands(self) -> int:
        return sum(len(f.commands) for f in self.files)

    def file_count(self) -> int:
        return len(self.files)

    def parsed_file_count(self) -> int:
        return sum(1 for f in self.files if f.commands)

