let answered=0;const total=5;
function upScore(){document.getElementById('score').textContent=`${answered} / ${total} answered`;}
function shuf(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
